fn putw(b:&mut[u8],p:usize,n:i16){b[p..p+2].copy_from_slice(&n.to_le_bytes());}fn putd(b:&mut[u8],p:usize,n:u32){b[p..p+4].copy_from_slice(&n.to_le_bytes());}
