 if name=="V44-approach-roads.jsonl"{for y in 40..=41{for x in 8..=110{g.map.terrain_codes[y*128+x]=7;}}g.map.native_terrain_plane=g.map.terrain_codes.clone();for(i,row)in g.map.native_road_graph.as_mut().unwrap().regions.iter_mut().take(7).enumerate(){row.bounds=[(8+i as i16*12)*16,512,(20+i as i16*12)*16-1,800];row.waypoint=(14+i*12+40*128)as u16;for j in 0..7{row.next[j]=if i==j{j}else if j>i{i+1}else{i-1}as u8;}}}
