#[test]fn actual_native_approach_and_walking_records_compare_fieldwise(){let Some(root)=std::env::var_os("NATIVE_WALK_CALLER_DIRECTORY")else{return;};for name in["V44-walk-whole-acquire.jsonl","V44-approach-pool.jsonl","V44-approach-families.jsonl","V44-approach-roads.jsonl"]{let text=std::fs::read_to_string(std::path::Path::new(&root).join(name)).unwrap();let rows=text.lines().map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();for pair in rows.chunks_exact(2){let before=&pair[0];let after=&pair[1];let mut g=fixture(before,name);let mode=before["mode"].as_u64().unwrap();let scenario=before["scenario"].as_u64().unwrap();let mut state=None;
 if mode==0{assert!(g.run_native_attack_motion(0));}else if mode==1{assert!(g.run_native_attack_walk(0));}else{let(mut s,c)=g.attack_order_state(0).unwrap();s.family=decode(before["unit"].as_str().unwrap())[48];let p=if name=="V44-approach-roads.jsonl"{[1120,500+(scenario as i16/2)*156]}else if name=="V44-approach-pool.jsonl"&&scenario==11{[320,320]}else{[if scenario%2==0{344}else{700},320]};g.native_attack_approach(0,p,&mut s).unwrap();let c=g.attack_order_state(0).unwrap().1;g.store_attack_order_state(0,&s,&c);state=Some(s);}
 let label=format!("{name}:{scenario}");assert_eq!(g.native_route_boundary,None,"{label}");let got=projection_index(&g,before,state.as_ref(),0,"unit");let want=decode(after["unit"].as_str().unwrap());if got!=want{let diffs=got.iter().zip(&want).enumerate().filter(|(_, (a,b))|a!=b).map(|(i,(a,b))|format!("{i:02x}:{a:02x}/{b:02x}")).collect::<Vec<_>>();panic!("{label} raw192diff {}",diffs.join(" "));}assert_eq!(projection_index(&g,before,None,1,"target"),decode(after["target"].as_str().unwrap()),"{label}:target192");assert_eq!(g.native_group_rosters.pool[120].roster.as_slice(),decode(after["targetRow"].as_str().unwrap()),"{label}:targetRoster72");let rawpool=|n:&original_route_pool::Node|{let mut b=[0u8;8];putw(&mut b,0,n.point[0]);putw(&mut b,2,n.point[1]);putd(&mut b,4,n.next);b};let pool=g.native_routes.borrow();assert_eq!(pool.pool.nodes[..8].iter().flat_map(rawpool).collect::<Vec<_>>(),decode(after["primary"].as_str().unwrap()),"{label}:primary64");if let Some(hash)=after["poolHash"].as_u64(){let got=pool.pool.nodes[..4800].iter().flat_map(rawpool).fold(2166136261u32,|h,n|(h^u32::from(n)).wrapping_mul(16777619));assert_eq!(u64::from(got),hash,"{label}:all4800poolbytes");}drop(pool);assert_eq!(hardware(&g),decode(after["dummy"].as_str().unwrap()),"{label}:dummy44");assert_eq!(g.native_group_rosters.pool[0].roster.as_slice(),decode(after["row"].as_str().unwrap()),"{label}:roster72");assert_eq!(g.original_rng.words,std::array::from_fn(|i|after[format!("r{i}")].as_u64().unwrap()as u32),"{label}:5RNG");if let Some(b)=after["hardware"].as_str(){assert_eq!(g.native_hardware_pool[0].attributes.bytes.as_slice(),decode(b),"{label}:W44");}
 }}}

#[test]fn full_goal_pool_preserves_counter_and_clear_prefix_without_a_fake_start(){let mut g=field();g.spawn("grunt",0,640.,640.,10,None);g.spawn("grunt",1,1400.,640.,20,None);g.maintain_native_group_rosters();g.native_group_rosters.current_roster=g.native_group_rosters.group_slot(0,10);for n in &mut g.native_routes.get_mut().pool.nodes[..4800]{n.next=0;}let slot=g.units[0].native_slot.unwrap();g.native_routes.get_mut().managed[slot]=true;g.units[0].native_counter68=0;g.units[0].native_phase35=8;g.units[0].native_order5c=-5;g.native_group_rosters.members[slot].as_mut().unwrap().promotion.target_x=1;let(mut s,c)=g.attack_order_state(0).unwrap();let before61=s.motion61;assert_eq!(g.native_attack_approach(0,[700,320],&mut s),Ok(Outcome::GoalPoolFull));g.store_attack_order_state(0,&s,&c);assert_eq!(s.flags71&128,0);assert_eq!(s.motion61,before61);assert_eq!(s.phase,8);assert!(s.counter68>0);assert!(g.units[0].original_motion.is_none());assert_eq!(g.native_routes.borrow().pool.links[slot].primary,0);}

